"""Intrinsic evaluation for the data-only loop."""

from __future__ import annotations

from collections import Counter, defaultdict
from typing import Dict, Iterable, List, Mapping, Optional

from .models import (
    EvaluationReport,
    QualityDecision,
    TaskExecution,
    stable_hash,
    utc_now,
)


class DataQualityEvaluator:
    def evaluate(
        self,
        executions: Iterable[TaskExecution],
        decisions: Iterable[QualityDecision] = (),
        *,
        metadata: Optional[Dict[str, object]] = None,
    ) -> EvaluationReport:
        execution_list = list(executions)
        decision_by_candidate = {
            item.candidate_id: item for item in decisions
        }
        per_task_counts: Dict[str, Counter] = defaultdict(Counter)
        rejection_reasons: Counter = Counter()

        generated = valid = accepted = rejected = 0
        for execution in execution_list:
            task_name = (
                execution.candidate.task_name
                if execution.candidate
                else "unknown"
            )
            counts = per_task_counts[task_name]
            counts["requests"] += 1
            if execution.candidate:
                generated += 1
                counts["generated"] += 1
            if execution.succeeded:
                valid += 1
                counts["valid"] += 1
            else:
                for issue in execution.validation.issues:
                    rejection_reasons[f"generation:{issue}"] += 1

            if not execution.candidate:
                continue
            decision = decision_by_candidate.get(
                execution.candidate.candidate_id
            )
            if not decision:
                continue
            if decision.decision == "accept":
                accepted += 1
                counts["accepted"] += 1
            else:
                rejected += 1
                counts["rejected"] += 1
                for reason in decision.reject_reasons:
                    rejection_reasons[f"quality:{reason}"] += 1

        per_task: Dict[str, Dict[str, object]] = {}
        for task_name, counts in per_task_counts.items():
            task_generated = counts["generated"]
            task_accepted = counts["accepted"]
            per_task[task_name] = {
                **dict(counts),
                "valid_yield": (
                    counts["valid"] / task_generated if task_generated else 0.0
                ),
                "accept_yield": (
                    task_accepted / task_generated if task_generated else 0.0
                ),
            }

        totals = {
            "requests": len(execution_list),
            "generated": generated,
            "valid": valid,
            "accepted": accepted,
            "rejected": rejected,
            "valid_yield": valid / generated if generated else 0.0,
            "accept_yield": accepted / generated if generated else 0.0,
        }
        report_id = stable_hash(
            totals,
            per_task,
            dict(rejection_reasons),
            metadata or {},
            prefix="evaluation",
        )
        return EvaluationReport(
            report_id=report_id,
            created_at=utc_now(),
            totals=totals,
            per_task=per_task,
            rejection_reasons=dict(rejection_reasons),
            metadata=metadata or {},
        )

"""Provider-neutral JSON LLM clients."""

from __future__ import annotations

import json
import os
import time
import urllib.error
import urllib.request
from dataclasses import dataclass, field
from typing import Any, Dict, Iterable, List, Mapping, Optional, Protocol, Sequence

from .models import canonical_json, stable_hash


@dataclass
class LLMResponse:
    content: Dict[str, Any]
    model: str
    request_id: Optional[str] = None
    usage: Dict[str, Any] = field(default_factory=dict)
    raw_response_hash: Optional[str] = None

    def __post_init__(self) -> None:
        if self.raw_response_hash is None:
            self.raw_response_hash = stable_hash(self.content, prefix="response")


class LLMClient(Protocol):
    def generate_json(
        self,
        *,
        messages: Sequence[Mapping[str, str]],
        output_schema: Mapping[str, Any],
        model: Optional[str] = None,
        parameters: Optional[Mapping[str, Any]] = None,
    ) -> LLMResponse:
        ...


class ReplayLLMClient:
    """Deterministic client backed by recorded JSON responses."""

    def __init__(
        self,
        responses: Iterable[Mapping[str, Any]],
        *,
        model: str = "replay-model",
    ) -> None:
        self._responses = iter(responses)
        self.model = model
        self.calls: List[Dict[str, Any]] = []

    def generate_json(
        self,
        *,
        messages: Sequence[Mapping[str, str]],
        output_schema: Mapping[str, Any],
        model: Optional[str] = None,
        parameters: Optional[Mapping[str, Any]] = None,
    ) -> LLMResponse:
        self.calls.append(
            {
                "messages": [dict(item) for item in messages],
                "output_schema": dict(output_schema),
                "model": model,
                "parameters": dict(parameters or {}),
            }
        )
        try:
            content = dict(next(self._responses))
        except StopIteration as exc:
            raise RuntimeError("ReplayLLMClient has no response left") from exc
        return LLMResponse(
            content=content,
            model=model or self.model,
            request_id=f"replay-{len(self.calls)}",
        )


class OpenAICompatibleClient:
    """Minimal JSON client for OpenAI-compatible chat-completions endpoints.

    The implementation uses only the Python standard library so local vLLM or
    remote compatible endpoints can be used without forcing an SDK dependency.
    """

    def __init__(
        self,
        *,
        base_url: str,
        model: str,
        api_key: Optional[str] = None,
        timeout: float = 120.0,
        max_retries: int = 3,
    ) -> None:
        if not base_url:
            raise ValueError("base_url is required")
        if not model:
            raise ValueError("model is required")
        self.base_url = base_url.rstrip("/")
        self.model = model
        self.api_key = api_key
        self.timeout = timeout
        self.max_retries = max_retries

    @classmethod
    def from_env(cls, prefix: str = "DSP_LLM") -> "OpenAICompatibleClient":
        base_url = os.environ.get(f"{prefix}_BASE_URL", "")
        model = os.environ.get(f"{prefix}_MODEL", "")
        api_key = os.environ.get(f"{prefix}_API_KEY")
        return cls(base_url=base_url, model=model, api_key=api_key)

    @property
    def endpoint(self) -> str:
        if self.base_url.endswith("/chat/completions"):
            return self.base_url
        if self.base_url.endswith("/v1"):
            return f"{self.base_url}/chat/completions"
        return f"{self.base_url}/v1/chat/completions"

    def generate_json(
        self,
        *,
        messages: Sequence[Mapping[str, str]],
        output_schema: Mapping[str, Any],
        model: Optional[str] = None,
        parameters: Optional[Mapping[str, Any]] = None,
    ) -> LLMResponse:
        schema_message = {
            "role": "system",
            "content": (
                "Return only one JSON object matching this schema. "
                f"Do not add markdown: {canonical_json(output_schema)}"
            ),
        }
        payload: Dict[str, Any] = {
            "model": model or self.model,
            "messages": [dict(item) for item in messages] + [schema_message],
            "response_format": {"type": "json_object"},
        }
        payload.update(dict(parameters or {}))
        request_body = json.dumps(payload, ensure_ascii=False).encode("utf-8")
        headers = {"Content-Type": "application/json"}
        if self.api_key:
            headers["Authorization"] = f"Bearer {self.api_key}"

        last_error: Optional[Exception] = None
        for attempt in range(self.max_retries):
            request = urllib.request.Request(
                self.endpoint,
                data=request_body,
                headers=headers,
                method="POST",
            )
            try:
                with urllib.request.urlopen(request, timeout=self.timeout) as response:
                    raw = response.read()
                decoded = json.loads(raw.decode("utf-8"))
                choice = decoded["choices"][0]["message"]["content"]
                if isinstance(choice, str):
                    content = json.loads(choice)
                elif isinstance(choice, dict):
                    content = choice
                else:
                    raise ValueError("LLM response content is not a JSON object")
                if not isinstance(content, dict):
                    raise ValueError("LLM response JSON must be an object")
                return LLMResponse(
                    content=content,
                    model=str(decoded.get("model", model or self.model)),
                    request_id=decoded.get("id"),
                    usage=dict(decoded.get("usage", {})),
                    raw_response_hash=stable_hash(decoded, prefix="response"),
                )
            except (
                urllib.error.URLError,
                urllib.error.HTTPError,
                KeyError,
                IndexError,
                TypeError,
                ValueError,
                json.JSONDecodeError,
            ) as exc:
                last_error = exc
                if attempt + 1 < self.max_retries:
                    time.sleep(min(2**attempt, 8))
        raise RuntimeError(
            f"LLM request failed after {self.max_retries} attempts: {last_error}"
        ) from last_error

"""Core contracts for independent data tasks."""

from __future__ import annotations

import hashlib
import json
import re
from dataclasses import asdict, dataclass, field
from datetime import datetime, timezone
from typing import Any, Dict, Iterable, List, Mapping, Optional, Sequence

_TEMPLATE_PATTERN = re.compile(r"\{\{\s*([A-Za-z_][A-Za-z0-9_.]*)\s*\}\}")


def utc_now() -> str:
    return datetime.now(timezone.utc).isoformat()


def canonical_json(value: Any) -> str:
    return json.dumps(
        value,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    )


def stable_hash(*values: Any, prefix: str = "sha256") -> str:
    digest = hashlib.sha256()
    for value in values:
        digest.update(canonical_json(value).encode("utf-8"))
        digest.update(b"\x1e")
    return f"{prefix}:{digest.hexdigest()}"


def _resolve_template_value(context: Mapping[str, Any], path: str) -> Any:
    value: Any = context
    for part in path.split("."):
        if not isinstance(value, Mapping) or part not in value:
            raise KeyError(f"Missing template variable: {path}")
        value = value[part]
    return value


def render_template(template: str, context: Mapping[str, Any]) -> str:
    """Render strict double-brace variables without executing template code."""

    def replace(match: re.Match) -> str:
        value = _resolve_template_value(context, match.group(1))
        if isinstance(value, (dict, list, tuple, bool, int, float)):
            return json.dumps(value, ensure_ascii=False, sort_keys=True)
        if value is None:
            return "null"
        return str(value)

    return _TEMPLATE_PATTERN.sub(replace, template)


@dataclass(frozen=True)
class SamplingPolicy:
    weight: float = 1.0
    min_weight: float = 0.0
    max_weight: float = 1.0
    max_delta: float = 1.0

    def validate(self) -> None:
        if self.min_weight < 0 or self.max_weight > 1:
            raise ValueError("Sampling bounds must be inside [0, 1]")
        if self.min_weight > self.max_weight:
            raise ValueError("min_weight cannot exceed max_weight")
        if not self.min_weight <= self.weight <= self.max_weight:
            raise ValueError("weight must be inside [min_weight, max_weight]")
        if self.max_delta < 0:
            raise ValueError("max_delta must be non-negative")


@dataclass(frozen=True)
class TaskDefinition:
    name: str
    version: str
    kind: str
    description: str
    system_prompt: str
    user_prompt: str
    output_schema: Dict[str, Any]
    model: Optional[str] = None
    parameters: Dict[str, Any] = field(default_factory=dict)
    sampling: SamplingPolicy = field(default_factory=SamplingPolicy)
    editable_fields: Sequence[str] = field(
        default_factory=lambda: (
            "system_prompt",
            "user_prompt",
            "parameters",
            "sampling.weight",
        )
    )

    @property
    def definition_id(self) -> str:
        return stable_hash(self.to_dict(), prefix="task")

    def validate(self) -> None:
        if not self.name or not self.version or not self.kind:
            raise ValueError("Task definition requires name, version, and kind")
        if not self.system_prompt.strip() or not self.user_prompt.strip():
            raise ValueError("Task prompts cannot be empty")
        if not isinstance(self.output_schema, dict):
            raise ValueError("output_schema must be an object")
        self.sampling.validate()

    def render_user_prompt(self, context: Mapping[str, Any]) -> str:
        return render_template(self.user_prompt, context)

    def to_dict(self) -> Dict[str, Any]:
        value = asdict(self)
        value["editable_fields"] = list(self.editable_fields)
        return value

    @classmethod
    def from_dict(cls, value: Mapping[str, Any]) -> "TaskDefinition":
        sampling = SamplingPolicy(**dict(value.get("sampling", {})))
        definition = cls(
            name=str(value["name"]),
            version=str(value["version"]),
            kind=str(value["kind"]),
            description=str(value.get("description", "")),
            system_prompt=str(value["system_prompt"]),
            user_prompt=str(value["user_prompt"]),
            output_schema=dict(value.get("output_schema", {})),
            model=value.get("model"),
            parameters=dict(value.get("parameters", {})),
            sampling=sampling,
            editable_fields=tuple(value.get("editable_fields", ())),
        )
        definition.validate()
        return definition


@dataclass(frozen=True)
class TaskRequest:
    input_id: str
    payload: Dict[str, Any]
    metadata: Dict[str, Any] = field(default_factory=dict)


@dataclass
class ValidationResult:
    passed: bool
    issues: List[str] = field(default_factory=list)
    checks: Dict[str, Any] = field(default_factory=dict)

    @classmethod
    def from_issues(
        cls,
        issues: Iterable[str],
        *,
        checks: Optional[Dict[str, Any]] = None,
    ) -> "ValidationResult":
        issue_list = list(issues)
        return cls(not issue_list, issue_list, checks or {})

    def to_dict(self) -> Dict[str, Any]:
        return asdict(self)


@dataclass
class TaskCandidate:
    candidate_id: str
    task_name: str
    task_version: str
    base_task_type: str
    generation_mode: str
    payload: Dict[str, Any]
    parent_ids: List[str] = field(default_factory=list)
    transformations: List[str] = field(default_factory=list)
    metadata: Dict[str, Any] = field(default_factory=dict)
    private_payload: Dict[str, Any] = field(default_factory=dict, repr=False)
    created_at: str = field(default_factory=utc_now)

    def to_dict(self, *, include_private: bool = False) -> Dict[str, Any]:
        value = asdict(self)
        if not include_private:
            value.pop("private_payload", None)
        return value

    @classmethod
    def from_dict(cls, value: Mapping[str, Any]) -> "TaskCandidate":
        return cls(
            candidate_id=str(value["candidate_id"]),
            task_name=str(value["task_name"]),
            task_version=str(value["task_version"]),
            base_task_type=str(value["base_task_type"]),
            generation_mode=str(value["generation_mode"]),
            payload=dict(value["payload"]),
            parent_ids=list(value.get("parent_ids", [])),
            transformations=list(value.get("transformations", [])),
            metadata=dict(value.get("metadata", {})),
            private_payload=dict(value.get("private_payload", {})),
            created_at=str(value.get("created_at", utc_now())),
        )


@dataclass
class TaskExecution:
    candidate: Optional[TaskCandidate]
    validation: ValidationResult
    raw_response_hash: Optional[str] = None
    request_id: Optional[str] = None
    error: Optional[str] = None

    @property
    def succeeded(self) -> bool:
        return self.candidate is not None and self.validation.passed and not self.error

    def to_dict(self, *, include_private: bool = False) -> Dict[str, Any]:
        return {
            "candidate": (
                self.candidate.to_dict(include_private=include_private)
                if self.candidate
                else None
            ),
            "validation": self.validation.to_dict(),
            "raw_response_hash": self.raw_response_hash,
            "request_id": self.request_id,
            "error": self.error,
            "succeeded": self.succeeded,
        }


@dataclass
class QualityDecision:
    candidate_id: str
    decision: str
    hard_fail: bool
    rule_results: List[Dict[str, Any]]
    small_model: Dict[str, Any]
    judge: Dict[str, Any]
    reject_reasons: List[str]
    policy_version: str
    created_at: str = field(default_factory=utc_now)

    def to_dict(self) -> Dict[str, Any]:
        return asdict(self)


@dataclass
class EvaluationReport:
    report_id: str
    created_at: str
    totals: Dict[str, Any]
    per_task: Dict[str, Dict[str, Any]]
    rejection_reasons: Dict[str, int]
    metadata: Dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> Dict[str, Any]:
        return asdict(self)

"""LLM-proposed, deterministically validated data-task modifications."""

from __future__ import annotations

from dataclasses import asdict, dataclass, replace
from typing import Any, Dict, Iterable, List, Mapping, Optional, Sequence, Tuple

from .llm import LLMClient
from .models import (
    EvaluationReport,
    SamplingPolicy,
    TaskDefinition,
    stable_hash,
    utc_now,
)
from .tasks.base import validate_json_schema_subset


@dataclass
class PromptProposal:
    proposal_id: str
    target_definition_id: str
    candidate_definition: TaskDefinition
    hypothesis: str
    expected_effects: List[str]
    risks: List[str]
    created_at: str

    def to_dict(self) -> Dict[str, Any]:
        value = asdict(self)
        value["candidate_definition"] = self.candidate_definition.to_dict()
        return value


@dataclass
class MixtureProposal:
    proposal_id: str
    raw_weights: Dict[str, float]
    projected_weights: Dict[str, float]
    rationale: Dict[str, str]
    constraints: Dict[str, Dict[str, float]]
    created_at: str

    def to_dict(self) -> Dict[str, Any]:
        return asdict(self)


class PromptOptimizer:
    """Ask an LLM for a candidate task definition; never auto-promote it."""

    def __init__(
        self,
        optimizer_definition: TaskDefinition,
        llm: LLMClient,
    ) -> None:
        if optimizer_definition.kind != "optimizer":
            raise ValueError("optimizer_definition must have kind=optimizer")
        self.definition = optimizer_definition
        self.llm = llm

    def propose(
        self,
        *,
        target: TaskDefinition,
        report: EvaluationReport,
        error_examples: Sequence[Mapping[str, Any]] = (),
    ) -> PromptProposal:
        context = {
            "target_definition": target.to_dict(),
            "evaluation_report": report.to_dict(),
            "error_examples": list(error_examples),
            "editable_fields": list(target.editable_fields),
        }
        response = self.llm.generate_json(
            messages=(
                {"role": "system", "content": self.definition.system_prompt},
                {
                    "role": "user",
                    "content": self.definition.render_user_prompt(context),
                },
            ),
            output_schema=self.definition.output_schema,
            model=self.definition.model,
            parameters=self.definition.parameters,
        )
        issues = validate_json_schema_subset(
            response.content,
            self.definition.output_schema,
        )
        if issues:
            raise ValueError(f"Invalid prompt proposal: {issues}")

        proposed_updates: Dict[str, Any] = {}
        if "system_prompt" in response.content:
            self._ensure_editable(target, "system_prompt")
            proposed_updates["system_prompt"] = str(
                response.content["system_prompt"]
            )
        if "user_prompt" in response.content:
            self._ensure_editable(target, "user_prompt")
            proposed_updates["user_prompt"] = str(response.content["user_prompt"])
        if "parameters" in response.content:
            self._ensure_editable(target, "parameters")
            proposed_updates["parameters"] = dict(response.content["parameters"])
        if not proposed_updates:
            raise ValueError("Prompt proposal did not modify an editable field")

        content_hash = stable_hash(
            target.definition_id,
            proposed_updates,
            prefix="prompt-proposal",
        )
        candidate = replace(
            target,
            version=f"{target.version}.candidate.{content_hash[-8:]}",
            **proposed_updates,
        )
        candidate.validate()
        return PromptProposal(
            proposal_id=content_hash,
            target_definition_id=target.definition_id,
            candidate_definition=candidate,
            hypothesis=str(response.content.get("hypothesis", "")),
            expected_effects=list(response.content.get("expected_effects", [])),
            risks=list(response.content.get("risks", [])),
            created_at=utc_now(),
        )

    @staticmethod
    def _ensure_editable(target: TaskDefinition, field_name: str) -> None:
        if field_name not in target.editable_fields:
            raise ValueError(f"Field is not editable: {field_name}")


def project_bounded_simplex(
    raw_weights: Mapping[str, float],
    bounds: Mapping[str, Tuple[float, float]],
    *,
    tolerance: float = 1e-10,
    max_iterations: int = 100,
) -> Dict[str, float]:
    """Project positive task weights onto a box-constrained simplex."""

    names = sorted(bounds)
    if set(raw_weights) != set(names):
        raise ValueError("raw_weights and bounds must have identical task names")
    lower_sum = sum(bounds[name][0] for name in names)
    upper_sum = sum(bounds[name][1] for name in names)
    if lower_sum > 1 + tolerance or upper_sum < 1 - tolerance:
        raise ValueError("Infeasible bounds: require sum(lower) <= 1 <= sum(upper)")
    for name, (lower, upper) in bounds.items():
        if lower < 0 or upper > 1 or lower > upper:
            raise ValueError(f"Invalid bounds for {name}: {(lower, upper)}")

    values = {
        name: min(max(float(raw_weights[name]), bounds[name][0]), bounds[name][1])
        for name in names
    }
    if sum(max(value, 0.0) for value in values.values()) <= tolerance:
        values = {name: bounds[name][0] for name in names}

    for _ in range(max_iterations):
        difference = 1.0 - sum(values.values())
        if abs(difference) <= tolerance:
            break
        if difference > 0:
            capacities = {
                name: bounds[name][1] - values[name] for name in names
            }
        else:
            capacities = {
                name: values[name] - bounds[name][0] for name in names
            }
        capacity_sum = sum(value for value in capacities.values() if value > 0)
        if capacity_sum <= tolerance:
            raise ValueError("Cannot satisfy simplex with provided bounds")
        for name in names:
            capacity = max(capacities[name], 0.0)
            if not capacity:
                continue
            delta = difference * capacity / capacity_sum
            values[name] = min(
                max(values[name] + delta, bounds[name][0]),
                bounds[name][1],
            )
    if abs(sum(values.values()) - 1.0) > 1e-8:
        raise ValueError("Simplex projection did not converge")
    return values


class MixturePlanner:
    """Ask an LLM for weights, then enforce deterministic task constraints."""

    def __init__(
        self,
        planner_definition: TaskDefinition,
        llm: LLMClient,
    ) -> None:
        if planner_definition.kind != "planner":
            raise ValueError("planner_definition must have kind=planner")
        self.definition = planner_definition
        self.llm = llm

    def propose(
        self,
        *,
        tasks: Sequence[TaskDefinition],
        report: EvaluationReport,
    ) -> MixtureProposal:
        generators = [item for item in tasks if item.kind == "generator"]
        if not generators:
            raise ValueError("At least one generator task is required")
        current = {item.name: item.sampling.weight for item in generators}
        constraints: Dict[str, Dict[str, float]] = {}
        bounds: Dict[str, Tuple[float, float]] = {}
        for item in generators:
            policy = item.sampling
            lower = max(policy.min_weight, policy.weight - policy.max_delta)
            upper = min(policy.max_weight, policy.weight + policy.max_delta)
            bounds[item.name] = (lower, upper)
            constraints[item.name] = {
                "current": policy.weight,
                "min": lower,
                "max": upper,
            }
        context = {
            "current_weights": current,
            "constraints": constraints,
            "evaluation_report": report.to_dict(),
        }
        response = self.llm.generate_json(
            messages=(
                {"role": "system", "content": self.definition.system_prompt},
                {
                    "role": "user",
                    "content": self.definition.render_user_prompt(context),
                },
            ),
            output_schema=self.definition.output_schema,
            model=self.definition.model,
            parameters=self.definition.parameters,
        )
        issues = validate_json_schema_subset(
            response.content,
            self.definition.output_schema,
        )
        if issues:
            raise ValueError(f"Invalid mixture proposal: {issues}")
        raw = {
            name: float(value)
            for name, value in dict(response.content.get("weights", {})).items()
        }
        if set(raw) != set(current):
            raise ValueError("Planner must propose exactly one weight per task")
        projected = project_bounded_simplex(raw, bounds)
        rationale = {
            str(name): str(reason)
            for name, reason in dict(
                response.content.get("rationale", {})
            ).items()
        }
        proposal_id = stable_hash(
            report.report_id,
            current,
            raw,
            projected,
            prefix="mixture-proposal",
        )
        return MixtureProposal(
            proposal_id=proposal_id,
            raw_weights=raw,
            projected_weights=projected,
            rationale=rationale,
            constraints=constraints,
            created_at=utc_now(),
        )

"""Independent deterministic + small-labeler + large-judge quality task."""

from __future__ import annotations

import ast
from typing import Any, Dict, List, Mapping, Optional, Sequence

from .llm import LLMClient
from .models import (
    QualityDecision,
    TaskCandidate,
    TaskDefinition,
    ValidationResult,
    stable_hash,
)
from .tasks.base import validate_json_schema_subset


class DeterministicQualityVerifier:
    """Low-cost checks shared by every quality policy."""

    _PLACEHOLDER_VALUES = {
        "",
        "todo",
        "tbd",
        "placeholder",
        "待补充",
        "略",
    }

    def verify(self, candidate: TaskCandidate) -> ValidationResult:
        payload = candidate.payload
        issues: List[str] = []
        instruction = str(payload.get("instruction", "")).strip()
        response = str(
            payload.get("response", payload.get("solution", ""))
        ).strip()
        if instruction.lower() in self._PLACEHOLDER_VALUES:
            issues.append("invalid_instruction")
        if response.lower() in self._PLACEHOLDER_VALUES:
            issues.append("invalid_response")

        checks: Dict[str, Any] = {
            "instruction_length": len(instruction),
            "response_length": len(response),
            "base_task_type": candidate.base_task_type,
        }
        if candidate.base_task_type == "math":
            if not str(payload.get("reference_answer", "")).strip():
                issues.append("missing_reference_answer")
            if not payload.get("knowledge_points"):
                issues.append("missing_knowledge_points")
        elif candidate.base_task_type == "code":
            solution = str(payload.get("solution", response))
            if not payload.get("public_tests"):
                issues.append("missing_public_tests")
            if not (
                payload.get("private_test_set_hash")
                or candidate.private_payload.get("private_tests")
            ):
                issues.append("missing_private_tests")
            if payload.get("language") == "python" and solution:
                try:
                    module = ast.parse(solution)
                    checks["python_static_parse"] = "passed"
                    entry_point = payload.get("entry_point")
                    functions = {
                        node.name
                        for node in ast.walk(module)
                        if isinstance(
                            node,
                            (ast.FunctionDef, ast.AsyncFunctionDef),
                        )
                    }
                    if entry_point and entry_point not in functions:
                        issues.append("entry_point_not_found")
                except SyntaxError:
                    checks["python_static_parse"] = "failed"
                    issues.append("python_syntax_error")
        return ValidationResult.from_issues(issues, checks=checks)


class QualityFilterTask:
    """Run one candidate through independent filter stages.

    Deterministic hard failures stop before model calls.  Every candidate that
    clears hard checks receives both a small-model label and a large-model
    judgment in the MVP so the two stages can later be calibrated.
    """

    def __init__(
        self,
        *,
        label_definition: TaskDefinition,
        judge_definition: TaskDefinition,
        labeler: LLMClient,
        judge: LLMClient,
        accept_probability_threshold: float = 0.7,
        verifier: Optional[DeterministicQualityVerifier] = None,
    ) -> None:
        if label_definition.kind != "labeler":
            raise ValueError("label_definition must have kind=labeler")
        if judge_definition.kind != "judge":
            raise ValueError("judge_definition must have kind=judge")
        if not 0 <= accept_probability_threshold <= 1:
            raise ValueError("accept_probability_threshold must be in [0, 1]")
        self.label_definition = label_definition
        self.judge_definition = judge_definition
        self.labeler = labeler
        self.judge = judge
        self.accept_probability_threshold = accept_probability_threshold
        self.verifier = verifier or DeterministicQualityVerifier()
        self.policy_version = stable_hash(
            label_definition.definition_id,
            judge_definition.definition_id,
            accept_probability_threshold,
            prefix="filter-policy",
        )

    def run(self, candidate: TaskCandidate) -> QualityDecision:
        verification = self.verifier.verify(candidate)
        rule_results = [
            {
                "name": "deterministic_quality",
                "passed": verification.passed,
                "issues": verification.issues,
                "checks": verification.checks,
            }
        ]
        if not verification.passed:
            return QualityDecision(
                candidate_id=candidate.candidate_id,
                decision="reject",
                hard_fail=True,
                rule_results=rule_results,
                small_model={},
                judge={},
                reject_reasons=list(verification.issues),
                policy_version=self.policy_version,
            )

        public_candidate = candidate.to_dict(include_private=False)
        context = {
            "candidate": public_candidate,
            "verification": verification.to_dict(),
        }
        label_response = self.labeler.generate_json(
            messages=(
                {
                    "role": "system",
                    "content": self.label_definition.system_prompt,
                },
                {
                    "role": "user",
                    "content": self.label_definition.render_user_prompt(context),
                },
            ),
            output_schema=self.label_definition.output_schema,
            model=self.label_definition.model,
            parameters=self.label_definition.parameters,
        )
        label_issues = validate_json_schema_subset(
            label_response.content,
            self.label_definition.output_schema,
        )
        if label_issues:
            raise ValueError(f"Invalid small-model labels: {label_issues}")

        judge_context = {
            **context,
            "small_model_labels": label_response.content,
        }
        judge_response = self.judge.generate_json(
            messages=(
                {
                    "role": "system",
                    "content": self.judge_definition.system_prompt,
                },
                {
                    "role": "user",
                    "content": self.judge_definition.render_user_prompt(
                        judge_context
                    ),
                },
            ),
            output_schema=self.judge_definition.output_schema,
            model=self.judge_definition.model,
            parameters=self.judge_definition.parameters,
        )
        judge_issues = validate_json_schema_subset(
            judge_response.content,
            self.judge_definition.output_schema,
        )
        if judge_issues:
            raise ValueError(f"Invalid judge result: {judge_issues}")

        probability = float(label_response.content.get("accept_probability", 0))
        judge_decision = str(
            judge_response.content.get("decision", "review")
        ).lower()
        hard_fail = bool(judge_response.content.get("hard_fail", False))
        reject_reasons: List[str] = []
        if probability < self.accept_probability_threshold:
            reject_reasons.append("small_model_below_threshold")
        if hard_fail:
            reject_reasons.append("judge_hard_fail")
        if judge_decision != "accept":
            reject_reasons.append(f"judge_decision:{judge_decision}")
        decision = "accept" if not reject_reasons else "reject"
        return QualityDecision(
            candidate_id=candidate.candidate_id,
            decision=decision,
            hard_fail=hard_fail,
            rule_results=rule_results,
            small_model={
                **label_response.content,
                "_model": label_response.model,
                "_request_id": label_response.request_id,
            },
            judge={
                **judge_response.content,
                "_model": judge_response.model,
                "_request_id": judge_response.request_id,
            },
            reject_reasons=reject_reasons,
            policy_version=self.policy_version,
        )

"""Versioned task-definition registry."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Dict, Iterable, List, Optional, Union

from .models import TaskDefinition
from .utils import atomic_write_json


class TaskRegistry:
    def __init__(self, definitions: Optional[Iterable[TaskDefinition]] = None) -> None:
        self._definitions: Dict[str, Dict[str, TaskDefinition]] = {}
        for definition in definitions or ():
            self.register(definition)

    def register(self, definition: TaskDefinition) -> None:
        definition.validate()
        versions = self._definitions.setdefault(definition.name, {})
        if definition.version in versions:
            raise ValueError(
                f"Duplicate task definition: {definition.name}@{definition.version}"
            )
        versions[definition.version] = definition

    def get(self, name: str, version: Optional[str] = None) -> TaskDefinition:
        if name not in self._definitions:
            raise KeyError(f"Unknown task: {name}")
        versions = self._definitions[name]
        selected = version or sorted(versions)[-1]
        if selected not in versions:
            raise KeyError(f"Unknown task version: {name}@{selected}")
        return versions[selected]

    def list(self, *, kind: Optional[str] = None) -> List[TaskDefinition]:
        definitions = [
            definition
            for versions in self._definitions.values()
            for definition in versions.values()
        ]
        if kind is not None:
            definitions = [item for item in definitions if item.kind == kind]
        return sorted(definitions, key=lambda item: (item.name, item.version))

    @classmethod
    def from_directory(cls, directory: Union[str, Path]) -> "TaskRegistry":
        root = Path(directory)
        registry = cls()
        for path in sorted(root.glob("*.json")):
            with path.open("r", encoding="utf-8") as stream:
                registry.register(TaskDefinition.from_dict(json.load(stream)))
        if not registry._definitions:
            raise ValueError(f"No task definitions found in {root}")
        return registry

    def save_candidate(
        self,
        definition: TaskDefinition,
        output_path: Union[str, Path],
    ) -> None:
        definition.validate()
        atomic_write_json(output_path, definition.to_dict())

"""Base implementation for an independently runnable LLM data task."""

from __future__ import annotations

from abc import ABC, abstractmethod
from typing import Any, Dict, List, Mapping, Optional, Sequence

from ..llm import LLMClient, LLMResponse
from ..models import (
    TaskCandidate,
    TaskDefinition,
    TaskExecution,
    TaskRequest,
    ValidationResult,
    stable_hash,
)

_JSON_TYPES = {
    "object": dict,
    "array": list,
    "string": str,
    "integer": int,
    "number": (int, float),
    "boolean": bool,
    "null": type(None),
}


def validate_json_schema_subset(
    value: Mapping[str, Any],
    schema: Mapping[str, Any],
) -> List[str]:
    """Validate the JSON-Schema subset used by task definitions."""

    issues: List[str] = []
    for field_name in schema.get("required", []):
        if field_name not in value:
            issues.append(f"missing_required_field:{field_name}")
    for field_name, field_schema in schema.get("properties", {}).items():
        if field_name not in value:
            continue
        expected_name = field_schema.get("type")
        if expected_name in _JSON_TYPES:
            expected_type = _JSON_TYPES[expected_name]
            field_value = value[field_name]
            if expected_name in {"integer", "number"} and isinstance(field_value, bool):
                issues.append(f"invalid_type:{field_name}:{expected_name}")
            elif not isinstance(field_value, expected_type):
                issues.append(f"invalid_type:{field_name}:{expected_name}")
        if "enum" in field_schema and value[field_name] not in field_schema["enum"]:
            issues.append(f"invalid_enum:{field_name}")
        if isinstance(value[field_name], (int, float)) and not isinstance(
            value[field_name], bool
        ):
            if "minimum" in field_schema and value[field_name] < field_schema["minimum"]:
                issues.append(f"below_minimum:{field_name}")
            if "maximum" in field_schema and value[field_name] > field_schema["maximum"]:
                issues.append(f"above_maximum:{field_name}")
    return issues


class LLMDataTask(ABC):
    """Generate one candidate from one request using a versioned definition."""

    base_task_type: str
    generation_mode: str

    def __init__(self, definition: TaskDefinition, llm: LLMClient) -> None:
        if definition.kind != "generator":
            raise ValueError(
                f"{definition.name} is kind={definition.kind}, expected generator"
            )
        self.definition = definition
        self.llm = llm

    def build_context(self, request: TaskRequest) -> Dict[str, Any]:
        return {
            **request.payload,
            "input_id": request.input_id,
            "metadata": request.metadata,
        }

    def build_messages(self, request: TaskRequest) -> Sequence[Mapping[str, str]]:
        user_prompt = self.definition.render_user_prompt(self.build_context(request))
        return (
            {"role": "system", "content": self.definition.system_prompt},
            {"role": "user", "content": user_prompt},
        )

    def run(self, request: TaskRequest) -> TaskExecution:
        try:
            response = self.llm.generate_json(
                messages=self.build_messages(request),
                output_schema=self.definition.output_schema,
                model=self.definition.model,
                parameters=self.definition.parameters,
            )
            schema_issues = validate_json_schema_subset(
                response.content,
                self.definition.output_schema,
            )
            candidate = self.build_candidate(request, response)
            validation = self.validate_candidate(request, candidate)
            validation.issues[:0] = schema_issues
            validation.passed = not validation.issues
            return TaskExecution(
                candidate=candidate,
                validation=validation,
                raw_response_hash=response.raw_response_hash,
                request_id=response.request_id,
            )
        except Exception as exc:
            return TaskExecution(
                candidate=None,
                validation=ValidationResult(
                    passed=False,
                    issues=[f"task_error:{type(exc).__name__}"],
                ),
                error=str(exc),
            )

    def make_candidate(
        self,
        *,
        request: TaskRequest,
        response: LLMResponse,
        payload: Dict[str, Any],
        base_task_type: Optional[str] = None,
        generation_mode: Optional[str] = None,
        parent_ids: Optional[List[str]] = None,
        transformations: Optional[List[str]] = None,
        private_payload: Optional[Dict[str, Any]] = None,
        metadata: Optional[Dict[str, Any]] = None,
    ) -> TaskCandidate:
        candidate_id = stable_hash(
            self.definition.definition_id,
            request.input_id,
            payload,
            parent_ids or [],
            prefix="candidate",
        )
        generation_metadata = {
            "definition_id": self.definition.definition_id,
            "model": response.model,
            "request_id": response.request_id,
            "usage": response.usage,
            "input_id": request.input_id,
            **request.metadata,
            **(metadata or {}),
        }
        return TaskCandidate(
            candidate_id=candidate_id,
            task_name=self.definition.name,
            task_version=self.definition.version,
            base_task_type=base_task_type or self.base_task_type,
            generation_mode=generation_mode or self.generation_mode,
            payload=payload,
            parent_ids=parent_ids or [],
            transformations=transformations or [],
            metadata=generation_metadata,
            private_payload=private_payload or {},
        )

    @abstractmethod
    def build_candidate(
        self,
        request: TaskRequest,
        response: LLMResponse,
    ) -> TaskCandidate:
        ...

    @abstractmethod
    def validate_candidate(
        self,
        request: TaskRequest,
        candidate: TaskCandidate,
    ) -> ValidationResult:
        ...

"""Question-solution-test code task generation."""

from __future__ import annotations

import ast
from typing import Any, Dict, List

from ..llm import LLMResponse
from ..models import TaskCandidate, TaskRequest, ValidationResult, stable_hash
from .base import LLMDataTask


class CodeGenerationTask(LLMDataTask):
    base_task_type = "code"
    generation_mode = "from_spec"

    def build_candidate(
        self,
        request: TaskRequest,
        response: LLMResponse,
    ) -> TaskCandidate:
        content = response.content
        public_tests = list(content.get("public_tests", []))
        private_tests = list(content.get("private_tests", []))
        private_hash = (
            stable_hash(private_tests, prefix="private-tests")
            if private_tests
            else None
        )
        payload = {
            "instruction": str(content.get("instruction", "")).strip(),
            "solution": str(content.get("solution", "")).strip(),
            "response": str(content.get("solution", "")).strip(),
            "language": str(
                content.get(
                    "language",
                    request.payload.get("language", "python"),
                )
            ).lower(),
            "entry_point": str(content.get("entry_point", "")).strip(),
            "public_tests": public_tests,
            "private_test_set_hash": private_hash,
            "algorithm_tags": list(content.get("algorithm_tags", [])),
            "difficulty": content.get(
                "difficulty",
                request.payload.get("difficulty", 1),
            ),
        }
        return self.make_candidate(
            request=request,
            response=response,
            payload=payload,
            private_payload={"private_tests": private_tests},
        )

    def validate_candidate(
        self,
        request: TaskRequest,
        candidate: TaskCandidate,
    ) -> ValidationResult:
        payload = candidate.payload
        issues: List[str] = []
        for field_name in ("instruction", "solution", "language", "entry_point"):
            if not payload.get(field_name):
                issues.append(f"empty_field:{field_name}")
        if not payload.get("public_tests"):
            issues.append("empty_field:public_tests")
        if not candidate.private_payload.get("private_tests"):
            issues.append("empty_field:private_tests")

        checks: Dict[str, Any] = {
            "static_parse": "not_run",
            "entry_point_found": False,
            "private_test_count": len(
                candidate.private_payload.get("private_tests", [])
            ),
        }
        if payload.get("language") == "python" and payload.get("solution"):
            try:
                module = ast.parse(payload["solution"])
                checks["static_parse"] = "passed"
                functions = {
                    node.name
                    for node in ast.walk(module)
                    if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
                }
                checks["entry_point_found"] = payload.get("entry_point") in functions
                if payload.get("entry_point") and not checks["entry_point_found"]:
                    issues.append("entry_point_not_found")
            except SyntaxError:
                checks["static_parse"] = "failed"
                issues.append("python_syntax_error")

        difficulty = payload.get("difficulty")
        if not isinstance(difficulty, int) or isinstance(difficulty, bool):
            issues.append("difficulty_must_be_integer")
        elif not 1 <= difficulty <= 5:
            issues.append("difficulty_out_of_range")
        return ValidationResult.from_issues(issues, checks=checks)

"""Math synthesis from explicit knowledge points."""

from __future__ import annotations

from typing import List

from ..llm import LLMResponse
from ..models import TaskCandidate, TaskRequest, ValidationResult
from .base import LLMDataTask


class MathKnowledgeTask(LLMDataTask):
    base_task_type = "math"
    generation_mode = "from_knowledge"

    def build_candidate(
        self,
        request: TaskRequest,
        response: LLMResponse,
    ) -> TaskCandidate:
        content = response.content
        requested_points = request.payload.get("knowledge_points", [])
        payload = {
            "instruction": str(content.get("instruction", "")).strip(),
            "response": str(content.get("response", "")).strip(),
            "reference_answer": str(content.get("reference_answer", "")).strip(),
            "knowledge_points": list(
                content.get("knowledge_points") or requested_points
            ),
            "solving_operations": list(content.get("solving_operations", [])),
            "difficulty": content.get(
                "difficulty",
                request.payload.get("difficulty", 1),
            ),
            "language": str(
                content.get("language", request.payload.get("language", "zh-CN"))
            ),
            "verification_level": str(
                content.get("verification_level", "judge_only")
            ),
        }
        return self.make_candidate(
            request=request,
            response=response,
            payload=payload,
        )

    def validate_candidate(
        self,
        request: TaskRequest,
        candidate: TaskCandidate,
    ) -> ValidationResult:
        payload = candidate.payload
        issues: List[str] = []
        for field_name in ("instruction", "response", "reference_answer"):
            if not payload.get(field_name):
                issues.append(f"empty_field:{field_name}")
        if not payload.get("knowledge_points"):
            issues.append("empty_field:knowledge_points")
        difficulty = payload.get("difficulty")
        if not isinstance(difficulty, int) or isinstance(difficulty, bool):
            issues.append("difficulty_must_be_integer")
        elif not 1 <= difficulty <= 5:
            issues.append("difficulty_out_of_range")

        requested = set(request.payload.get("knowledge_points", []))
        returned = set(payload.get("knowledge_points", []))
        missing = sorted(requested - returned)
        if missing:
            issues.append(f"missing_requested_knowledge_points:{','.join(missing)}")

        checks = {
            "requested_knowledge_points": sorted(requested),
            "returned_knowledge_points": sorted(returned),
            "has_reference_answer": bool(payload.get("reference_answer")),
        }
        return ValidationResult.from_issues(issues, checks=checks)

"""Semantics-preserving style, diversity, and language rewriting."""

from __future__ import annotations

import re
from typing import Any, Dict, List, Mapping

from ..llm import LLMResponse
from ..models import TaskCandidate, TaskRequest, ValidationResult, stable_hash
from .base import LLMDataTask

_NUMBER_PATTERN = re.compile(r"(?<![A-Za-z])[-+]?\d+(?:\.\d+)?")


class RewriteTask(LLMDataTask):
    base_task_type = "general"
    generation_mode = "rewrite"

    def build_context(self, request: TaskRequest) -> Dict[str, Any]:
        parent = self._parent(request)
        return {
            **request.payload,
            "input_id": request.input_id,
            "parent": parent,
            "parent_payload": parent["payload"],
            "metadata": request.metadata,
        }

    def build_candidate(
        self,
        request: TaskRequest,
        response: LLMResponse,
    ) -> TaskCandidate:
        parent = self._parent(request)
        parent_payload = dict(parent["payload"])
        content = response.content
        transformations = list(
            content.get("transformations")
            or request.payload.get("transformations", [])
        )
        payload = {
            **parent_payload,
            "instruction": str(content.get("instruction", "")).strip(),
            "language": str(
                content.get(
                    "language",
                    request.payload.get(
                        "target_language",
                        parent_payload.get("language", "zh-CN"),
                    ),
                )
            ),
            "style": str(
                content.get(
                    "style",
                    request.payload.get(
                        "target_style",
                        parent_payload.get("style", "default"),
                    ),
                )
            ),
            "rewrite_summary": str(content.get("rewrite_summary", "")).strip(),
        }
        parent_id = str(parent["candidate_id"])
        lineage_group_id = parent.get("metadata", {}).get(
            "lineage_group_id",
            stable_hash(parent_id, prefix="lineage"),
        )
        return self.make_candidate(
            request=request,
            response=response,
            payload=payload,
            base_task_type=str(parent["base_task_type"]),
            generation_mode="rewrite",
            parent_ids=[parent_id],
            transformations=transformations,
            metadata={"lineage_group_id": lineage_group_id},
        )

    def validate_candidate(
        self,
        request: TaskRequest,
        candidate: TaskCandidate,
    ) -> ValidationResult:
        parent = self._parent(request)
        original = str(parent["payload"].get("instruction", "")).strip()
        rewritten = str(candidate.payload.get("instruction", "")).strip()
        issues: List[str] = []
        if not rewritten:
            issues.append("empty_field:instruction")
        if rewritten == original:
            issues.append("rewrite_is_identical")
        if candidate.payload.get("reference_answer") != parent["payload"].get(
            "reference_answer"
        ):
            issues.append("reference_answer_changed")
        if candidate.payload.get("response") != parent["payload"].get("response"):
            issues.append("response_changed")

        if request.payload.get("preserve_numbers", True):
            original_numbers = sorted(_NUMBER_PATTERN.findall(original))
            rewritten_numbers = sorted(_NUMBER_PATTERN.findall(rewritten))
            if original_numbers != rewritten_numbers:
                issues.append("numeric_literals_changed")
        else:
            original_numbers = []
            rewritten_numbers = []

        target_language = request.payload.get("target_language")
        if target_language and candidate.payload.get("language") != target_language:
            issues.append("target_language_not_met")
        target_style = request.payload.get("target_style")
        if target_style and candidate.payload.get("style") != target_style:
            issues.append("target_style_not_met")

        return ValidationResult.from_issues(
            issues,
            checks={
                "original_numbers": original_numbers,
                "rewritten_numbers": rewritten_numbers,
                "parent_candidate_id": parent["candidate_id"],
            },
        )

    @staticmethod
    def _parent(request: TaskRequest) -> Mapping[str, Any]:
        parent = request.payload.get("parent")
        if isinstance(parent, TaskCandidate):
            parent = parent.to_dict()
        if not isinstance(parent, Mapping):
            raise ValueError("Rewrite task requires payload.parent")
        required = {"candidate_id", "base_task_type", "payload"}
        missing = required - set(parent)
        if missing:
            raise ValueError(f"Invalid parent candidate, missing: {sorted(missing)}")
        return parent

import json
import os
import tempfile
from pathlib import Path
from typing import Any, Dict, Iterable, Iterator, List, Union

PathLike = Union[str, os.PathLike]

# 读取jsonl里所有行到内存，返回一个列表
def read_jsonl(file_path):
    return list(iter_jsonl(file_path))


def iter_jsonl(file_path: PathLike) -> Iterator[Dict[str, Any]]:
    """Stream JSON objects from a JSONL file.

    Empty lines are ignored.  Errors include the source line number so a large
    run can be repaired without loading the complete file into memory.
    """

    with open(file_path, "r", encoding="utf-8") as stream:
        for line_number, line in enumerate(stream, start=1):
            if not line.strip():
                continue
            try:
                value = json.loads(line)
            except json.JSONDecodeError as exc:
                raise ValueError(
                    f"Invalid JSONL at {file_path}:{line_number}: {exc.msg}"
                ) from exc
            if not isinstance(value, dict):
                raise ValueError(
                    f"JSONL row must be an object at {file_path}:{line_number}"
                )
            yield value


def write_jsonl(
    file_path: PathLike,
    rows: Iterable[Dict[str, Any]],
    *,
    append: bool = False,
) -> None:
    """Write JSON objects as UTF-8 JSONL."""

    path = Path(file_path)
    path.parent.mkdir(parents=True, exist_ok=True)
    mode = "a" if append else "w"
    with path.open(mode, encoding="utf-8") as stream:
        for row in rows:
            stream.write(json.dumps(row, ensure_ascii=False, sort_keys=True))
            stream.write("\n")


def atomic_write_json(file_path: PathLike, value: Any) -> None:
    """Atomically replace a JSON artifact in the target directory."""

    path = Path(file_path)
    path.parent.mkdir(parents=True, exist_ok=True)
    descriptor, temporary_path = tempfile.mkstemp(
        prefix=f".{path.name}.",
        suffix=".tmp",
        dir=str(path.parent),
    )
    try:
        with os.fdopen(descriptor, "w", encoding="utf-8") as stream:
            json.dump(value, stream, ensure_ascii=False, indent=2, sort_keys=True)
            stream.write("\n")
        os.replace(temporary_path, path)
    except Exception:
        try:
            os.unlink(temporary_path)
        except FileNotFoundError:
            pass
        raise

# 读取parquet文件
def read_parquet(file_path):
    try:
        import pandas as pd
    except ImportError as exc:
        raise RuntimeError(
            "read_parquet requires the optional data dependencies; "
            "install with: pip install -e '.[data]'"
        ) from exc
    df = pd.read_parquet(file_path)
    return df

